def run_sql_query(database_id, sql_text, parameters_json=None, client_metadata_json=None, result_limit=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0285000" if __import__("os").path.isdir("./environment_mix/0285000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs + unexpected fields
    allowed = {"database_id", "sql_text", "parameters_json", "client_metadata_json", "result_limit"}
    unexpected = set(_extra.keys()) - {"_"}
    if unexpected:
        return _err("VALIDATION_ERROR", "Unexpected fields supplied.", unexpected_fields=sorted(list(unexpected)))
    if not isinstance(database_id, str) or not re.match(r"^mysqldb_[0-9A-Z]{20,30}$", database_id):
        return _err("VALIDATION_ERROR", "database_id is invalid.")
    if not isinstance(sql_text, str) or not sql_text.strip():
        return _err("VALIDATION_ERROR", "sql_text must be a non-empty string.")
    if len(sql_text) > 1_000_000:
        return _err("VALIDATION_ERROR", "sql_text exceeds maximum length of 1,000,000 characters.")
    if parameters_json is not None and not isinstance(parameters_json, dict):
        return _err("VALIDATION_ERROR", "parameters_json must be an object if provided.")
    if client_metadata_json is not None and not isinstance(client_metadata_json, dict):
        return _err("VALIDATION_ERROR", "client_metadata_json must be an object if provided.")
    if result_limit is None:
        result_limit = 1000
    if not isinstance(result_limit, int) or result_limit < 1 or result_limit > 10000:
        return _err("VALIDATION_ERROR", "result_limit must be an integer between 1 and 10000.")

    # Load stores
    api_keys = _load("api_keys.json")
    dbs = _load("mysql_databases.json")
    tables = _load("mysql_tables.json")
    sql_requests = _load("sql_requests.json")
    effects = _load("request_table_effects.json")

    # Resolve an active api key (ambient auth) that can serve the call, enforce limits against that key.
    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.date()

    now_dt = datetime.datetime.utcnow()

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available to authenticate the request.")

    # Database must exist and be enabled
    db_row = next((d for d in dbs if isinstance(d, dict) and d.get("id") == database_id), None)
    if not db_row:
        return _err("NOT_FOUND", "Database not found.", database_id=database_id)
    if db_row.get("status") != "enabled":
        return _err("INVALID_TRANSITION", "Database is disabled.", database_id=database_id)

    # choose a key that is under quota; if none, reject and optionally record failed sql_requests
    def _counts_for_key(key_id):
        per_min = 0
        per_day = 0
        for r in sql_requests:
            if not isinstance(r, dict): 
                continue
            if r.get("api_key_id") != key_id:
                continue
            created = _parse_dt(r.get("created_at"))
            if not created:
                continue
            # count all attempts (any status) as requests
            if _minute_bucket(created) == _minute_bucket(now_dt):
                per_min += 1
            if created.date() == _day_bucket(now_dt):
                per_day += 1
        return per_min, per_day

    chosen_key = None
    chosen_counts = None
    for k in active_keys:
        kid = k.get("id")
        if not isinstance(kid, str): 
            continue
        rpm = k.get("requests_per_minute_limit")
        dlim = k.get("daily_requests_limit")
        if not isinstance(rpm, int) or not isinstance(dlim, int):
            continue
        per_min, per_day = _counts_for_key(kid)
        if per_min + 1 <= rpm and per_day + 1 <= dlim:
            chosen_key = k
            chosen_counts = (per_min, per_day)
            break

    # Helper to make ids
    def _new_id(prefix, existing):
        chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        existing_ids = set([row.get("id") for row in existing if isinstance(row, dict)])
        # deterministic-ish with time+counter
        base = int(time.time() * 1000)
        for i in range(10000):
            v = base + i
            s = ""
            x = v
            for _ in range(24):
                s = chars[x % 36] + s
                x //= 36
            cand = f"{prefix}_{s[-24:]}"
            if cand not in existing_ids:
                return cand
        return f"{prefix}_{hashlib.sha1((str(base)).encode()).hexdigest()[:24].upper()}"

    # If quota exceeded: optionally record failed sql_request with error_code='quota_exceeded'
    if chosen_key is None:
        # pick any active key to attribute failure (best-effort)
        k = active_keys[0]
        rid = _new_id("sqlreq", sql_requests)
        created_at = now
        # queued -> running -> failed in same transaction (started_at set)
        started_at = now
        finished_at = now
        duration_ms = int((time.time() - t0) * 1000)
        req_row = {
            "id": rid,
            "api_key_id": k.get("id"),
            "database_id": database_id,
            "table_id": None,
            "tool_name": "run_sql_query",
            "operation_type": "read",
            "sql_text": sql_text,
            "parameters_json": parameters_json if parameters_json is not None else None,
            "status": "failed",
            "started_at": started_at,
            "finished_at": finished_at,
            "duration_ms": duration_ms if duration_ms >= 0 else 0,
            "rows_affected": None,
            "result_set_json": None,
            "result_truncated": False,
            "error_code": "quota_exceeded",
            "error_message": "Rate limit or daily quota exceeded.",
            "client_metadata_json": client_metadata_json if client_metadata_json is not None else None,
            "created_at": created_at,
            "updated_at": now,
        }
        sql_requests.append(req_row)
        # persist request log row
        _save("sql_requests.json", sql_requests)
        return _err("QUOTA_EXCEEDED", "Rate limit or daily quota exceeded.", api_key_id=k.get("id"))

    # Create sql_requests row exactly one
    api_key_id = chosen_key["id"]
    req_id = _new_id("sqlreq", sql_requests)
    created_at = now
    started_at = now  # transition through running in same transaction
    # Simulate execution (offline): succeed for read-like statements, fail for others
    normalized = sql_text.strip().lower()
    is_read = normalized.startswith("select") or normalized.startswith("with") or normalized.startswith("show") or normalized.startswith("describe") or normalized.startswith("explain")
    operation_type = "read" if is_read else ("ddl" if normalized.startswith(("create", "alter", "drop", "truncate")) else "dml")

    status = "succeeded"
    error_code = None
    error_message = None
    rows_affected = None
    result_set_json = None
    result_truncated = False

    # best-effort detect referenced tables for effects
    table_effects_to_add = []
    # map table_name->table_id in this database for active tables
    tbls_in_db = [t for t in tables if isinstance(t, dict) and t.get("database_id") == database_id]
    name_to_tbl = {t.get("table_name"): t for t in tbls_in_db if isinstance(t.get("table_name"), str)}
    # naive parse: capture tokens after FROM/JOIN/UPDATE/INTO
    candidates = []
    try:
        tokens = re.split(r"[\s,;()]+", sql_text.strip(), flags=re.IGNORECASE)
        for i, tok in enumerate(tokens):
            low = tok.lower()
            if low in ("from", "join", "update", "into"):
                if i + 1 < len(tokens):
                    candidates.append(tokens[i + 1].strip("`"))
    except Exception:
        candidates = []
    involved = []
    for c in candidates:
        # strip db qualifier
        if "." in c:
            c = c.split(".")[-1]
        if c in name_to_tbl:
            involved.append(name_to_tbl[c])
    # unique
    seen_tbl_ids = set()
    involved_unique = []
    for t in involved:
        tid = t.get("id")
        if isinstance(tid, str) and tid not in seen_tbl_ids:
            seen_tbl_ids.add(tid)
            involved_unique.append(t)

    # Generate a minimal synthetic result for read queries
    MAX_BYTES = 5 * 1024 * 1024
    if is_read:
        # Provide placeholder rows to allow testing; capped by result_limit
        # Do not fabricate schema beyond generic columns.
        rows = []
        n = min(result_limit, 5)
        for i in range(n):
            rows.append({"row_number": i + 1})
        result_set_json = {"rows": rows, "row_count": len(rows)}
        enc = json.dumps(result_set_json, ensure_ascii=False).encode("utf-8")
        if len(enc) > MAX_BYTES:
            # truncate rows
            result_truncated = True
            # keep as many rows as fit
            kept = []
            for r in rows:
                trial = {"rows": kept + [r], "row_count": len(kept) + 1}
                if len(json.dumps(trial, ensure_ascii=False).encode("utf-8")) > MAX_BYTES:
                    break
                kept.append(r)
            result_set_json = {"rows": kept, "row_count": len(kept)}
        # record effects as read
        for t in involved_unique:
            table_effects_to_add.append((t.get("id"), "read"))
    else:
        # For non-read in run_sql_query, mark succeeded but no result_set; effects unknown
        for t in involved_unique:
            table_effects_to_add.append((t.get("id"), "unknown"))

    finished_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    duration_ms = int((time.time() - t0) * 1000)
    if duration_ms < 0:
        duration_ms = 0

    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "database_id": database_id,
        "table_id": involved_unique[0].get("id") if involved_unique else None,
        "tool_name": "run_sql_query",
        "operation_type": operation_type if operation_type in ("ddl", "dml", "read", "admin") else "read",
        "sql_text": sql_text,
        "parameters_json": parameters_json if parameters_json is not None else None,
        "status": status,
        "started_at": started_at,
        "finished_at": finished_at,
        "duration_ms": duration_ms,
        "rows_affected": rows_affected,
        "result_set_json": result_set_json,
        "result_truncated": bool(result_truncated),
        "error_code": error_code,
        "error_message": error_message,
        "client_metadata_json": client_metadata_json if client_metadata_json is not None else None,
        "created_at": created_at,
        "updated_at": finished_at,
    }
    sql_requests.append(req_row)

    # Add request_table_effects best-effort; preserve uniqueness
    def _effects_key(sql_request_id, table_id, effect_type):
        return f"{sql_request_id}::{table_id}::{effect_type}"
    existing_eff = set()
    for e in effects:
        if isinstance(e, dict):
            existing_eff.add(_effects_key(e.get("sql_request_id"), e.get("table_id"), e.get("effect_type")))
    for (tid, et) in table_effects_to_add:
        if not isinstance(tid, str):
            continue
        if et not in ("read", "insert", "update", "delete", "ddl_create", "ddl_alter", "ddl_drop", "unknown"):
            et = "unknown"
        k = _effects_key(req_id, tid, et)
        if k in existing_eff:
            continue
        eff_row = {
            "id": _new_id("rteff", effects),
            "sql_request_id": req_id,
            "table_id": tid,
            "effect_type": et,
            "created_at": now,
            "updated_at": now,
        }
        effects.append(eff_row)
        existing_eff.add(k)

    # Update api key last_used_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            break

    _save("sql_requests.json", sql_requests)
    _save("request_table_effects.json", effects)
    _save("api_keys.json", api_keys)

    return {
        "sql_request": req_row,
        "result": req_row.get("result_set_json"),
        "meta": {
            "result_limit": result_limit,
            "result_truncated": req_row.get("result_truncated"),
        }
    }

def create_table(database_id, table_name, table_schema_json, engine=None, sql_text=None, client_metadata_json=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0285000" if __import__("os").path.isdir("./environment_mix/0285000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    unexpected = set(_extra.keys()) - {"_"}
    if unexpected:
        return _err("VALIDATION_ERROR", "Unexpected fields supplied.", unexpected_fields=sorted(list(unexpected)))
    if not isinstance(database_id, str) or not re.match(r"^mysqldb_[0-9A-Z]{20,30}$", database_id):
        return _err("VALIDATION_ERROR", "database_id is invalid.")
    if not isinstance(table_name, str) or not table_name.strip():
        return _err("VALIDATION_ERROR", "table_name must be a non-empty string.")
    if not re.match(r"^[A-Za-z0-9_]{1,64}$", table_name.strip()):
        return _err("VALIDATION_ERROR", "table_name must match ^[A-Za-z0-9_]{1,64}$.")
    if engine is not None and not isinstance(engine, str):
        return _err("VALIDATION_ERROR", "engine must be a string if provided.")
    if not isinstance(table_schema_json, dict):
        return _err("VALIDATION_ERROR", "table_schema_json must be an object.")
    if sql_text is not None:
        if not isinstance(sql_text, str) or not sql_text.strip():
            return _err("VALIDATION_ERROR", "sql_text must be a non-empty string if provided.")
        if len(sql_text) > 1_000_000:
            return _err("VALIDATION_ERROR", "sql_text exceeds maximum length of 1,000,000 characters.")
    if client_metadata_json is not None and not isinstance(client_metadata_json, dict):
        return _err("VALIDATION_ERROR", "client_metadata_json must be an object if provided.")

    api_keys = _load("api_keys.json")
    dbs = _load("mysql_databases.json")
    tables = _load("mysql_tables.json")
    sql_requests = _load("sql_requests.json")
    effects = _load("request_table_effects.json")

    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    now_dt = datetime.datetime.utcnow()
    def _minute_bucket(dt): return dt.replace(second=0, microsecond=0)
    def _day_bucket(dt): return dt.date()

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available to authenticate the request.")

    db_row = next((d for d in dbs if isinstance(d, dict) and d.get("id") == database_id), None)
    if not db_row:
        return _err("NOT_FOUND", "Database not found.", database_id=database_id)
    if db_row.get("status") != "enabled":
        return _err("INVALID_TRANSITION", "Database is disabled.", database_id=database_id)

    def _counts_for_key(key_id):
        per_min = 0
        per_day = 0
        for r in sql_requests:
            if not isinstance(r, dict): 
                continue
            if r.get("api_key_id") != key_id:
                continue
            created = _parse_dt(r.get("created_at"))
            if not created:
                continue
            if _minute_bucket(created) == _minute_bucket(now_dt):
                per_min += 1
            if created.date() == _day_bucket(now_dt):
                per_day += 1
        return per_min, per_day

    chosen_key = None
    for k in active_keys:
        kid = k.get("id")
        rpm = k.get("requests_per_minute_limit")
        dlim = k.get("daily_requests_limit")
        if not isinstance(kid, str) or not isinstance(rpm, int) or not isinstance(dlim, int):
            continue
        pm, pd = _counts_for_key(kid)
        if pm + 1 <= rpm and pd + 1 <= dlim:
            chosen_key = k
            break

    def _new_id(prefix, existing):
        chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        existing_ids = set([row.get("id") for row in existing if isinstance(row, dict)])
        base = int(time.time() * 1000)
        for i in range(10000):
            v = base + i
            s = ""
            x = v
            for _ in range(24):
                s = chars[x % 36] + s
                x //= 36
            cand = f"{prefix}_{s[-24:]}"
            if cand not in existing_ids:
                return cand
        return f"{prefix}_{hashlib.sha1((str(base)).encode()).hexdigest()[:24].upper()}"

    if chosen_key is None:
        # Optionally record failed request
        k = active_keys[0]
        req_id = _new_id("sqlreq", sql_requests)
        finished_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        duration_ms = int((time.time() - t0) * 1000)
        sql_requests.append({
            "id": req_id,
            "api_key_id": k.get("id"),
            "database_id": database_id,
            "table_id": None,
            "tool_name": "create_table",
            "operation_type": "ddl",
            "sql_text": sql_text if sql_text is not None else f"CREATE TABLE `{table_name}` (...)",
            "parameters_json": None,
            "status": "failed",
            "started_at": now,
            "finished_at": finished_at,
            "duration_ms": duration_ms if duration_ms >= 0 else 0,
            "rows_affected": None,
            "result_set_json": None,
            "result_truncated": False,
            "error_code": "quota_exceeded",
            "error_message": "Rate limit or daily quota exceeded.",
            "client_metadata_json": client_metadata_json if client_metadata_json is not None else None,
            "created_at": now,
            "updated_at": finished_at,
        })
        _save("sql_requests.json", sql_requests)
        return _err("QUOTA_EXCEEDED", "Rate limit or daily quota exceeded.", api_key_id=k.get("id"))

    # Check existing table uniqueness (database_id, table_name)
    existing = next((t for t in tables if isinstance(t, dict) and t.get("database_id") == database_id and t.get("table_name") == table_name), None)
    if_exists = False
    if sql_text is not None and re.search(r"\bif\s+not\s+exists\b", sql_text, flags=re.IGNORECASE):
        if_exists = True

    api_key_id = chosen_key["id"]
    req_id = _new_id("sqlreq", sql_requests)

    # Create sql_request row (exactly one)
    started_at = now

    status = "succeeded"
    error_code = None
    error_message = None
    rows_affected = 1
    created_table_row = None

    if existing is not None and existing.get("status") != "dropped":
        if if_exists:
            rows_affected = 0
            created_table_row = existing
        else:
            status = "failed"
            error_code = "table_exists"
            error_message = "Table already exists."
            rows_affected = None
    else:
        # create/restore table record
        if existing is None:
            tbl_id = _new_id("mysqltbl", tables)
            created_table_row = {
                "id": tbl_id,
                "database_id": database_id,
                "table_name": table_name,
                "engine": engine,
                "table_schema_json": table_schema_json,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            tables.append(created_table_row)
        else:
            # previously dropped; cannot transition dropped->active per lifecycle; treat as conflict
            status = "failed"
            error_code = "invalid_transition"
            error_message = "Cannot recreate a dropped table record; create a new table name."
            rows_affected = None

    sql_to_audit = sql_text if sql_text is not None else f"CREATE TABLE `{table_name}` (...)"
    if not isinstance(sql_to_audit, str) or not sql_to_audit.strip():
        return _err("VALIDATION_ERROR", "sql_text (generated or provided) must be non-empty.")
    if len(sql_to_audit) > 1_000_000:
        return _err("VALIDATION_ERROR", "sql_text exceeds maximum length of 1,000,000 characters.")

    finished_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    duration_ms = int((time.time() - t0) * 1000)
    if duration_ms < 0:
        duration_ms = 0

    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "database_id": database_id,
        "table_id": created_table_row.get("id") if isinstance(created_table_row, dict) else None,
        "tool_name": "create_table",
        "operation_type": "ddl",
        "sql_text": sql_to_audit,
        "parameters_json": None,
        "status": status,
        "started_at": started_at,
        "finished_at": finished_at,
        "duration_ms": duration_ms,
        "rows_affected": rows_affected,
        "result_set_json": None,
        "result_truncated": False,
        "error_code": error_code,
        "error_message": error_message,
        "client_metadata_json": client_metadata_json if client_metadata_json is not None else None,
        "created_at": now,
        "updated_at": finished_at,
    }
    sql_requests.append(req_row)

    # request_table_effects for DDL create (only on success and when table row exists)
    if status == "succeeded" and isinstance(created_table_row, dict) and isinstance(created_table_row.get("id"), str):
        # uniqueness
        sig = (req_id, created_table_row["id"], "ddl_create")
        for e in effects:
            if isinstance(e, dict) and (e.get("sql_request_id"), e.get("table_id"), e.get("effect_type")) == sig:
                break
        else:
            effects.append({
                "id": _new_id("rteff", effects),
                "sql_request_id": req_id,
                "table_id": created_table_row["id"],
                "effect_type": "ddl_create",
                "created_at": now,
                "updated_at": now,
            })

    # update api key last_used_at only on successful authentication (always here)
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            break

    _save("sql_requests.json", sql_requests)
    _save("mysql_tables.json", tables)
    _save("request_table_effects.json", effects)
    _save("api_keys.json", api_keys)

    if status != "succeeded":
        return _err("CONFLICT", "Create table failed.", sql_request=req_row)

    return {"table": created_table_row, "sql_request": req_row}

def insert_data(database_id, table_id, rows_json, client_metadata_json=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0285000" if __import__("os").path.isdir("./environment_mix/0285000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    unexpected = set(_extra.keys()) - {"_"}
    if unexpected:
        return _err("VALIDATION_ERROR", "Unexpected fields supplied.", unexpected_fields=sorted(list(unexpected)))
    if not isinstance(database_id, str) or not re.match(r"^mysqldb_[0-9A-Z]{20,30}$", database_id):
        return _err("VALIDATION_ERROR", "database_id is invalid.")
    if not isinstance(table_id, str) or not re.match(r"^mysqltbl_[0-9A-Z]{20,30}$", table_id):
        return _err("VALIDATION_ERROR", "table_id is invalid.")
    if not isinstance(rows_json, list) or len(rows_json) < 1 or any(not isinstance(r, dict) for r in rows_json):
        return _err("VALIDATION_ERROR", "rows_json must be a non-empty array of objects.")
    if client_metadata_json is not None and not isinstance(client_metadata_json, dict):
        return _err("VALIDATION_ERROR", "client_metadata_json must be an object if provided.")

    api_keys = _load("api_keys.json")
    dbs = _load("mysql_databases.json")
    tables = _load("mysql_tables.json")
    sql_requests = _load("sql_requests.json")
    effects = _load("request_table_effects.json")

    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    now_dt = datetime.datetime.utcnow()
    def _minute_bucket(dt): return dt.replace(second=0, microsecond=0)
    def _day_bucket(dt): return dt.date()

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available to authenticate the request.")

    db_row = next((d for d in dbs if isinstance(d, dict) and d.get("id") == database_id), None)
    if not db_row:
        return _err("NOT_FOUND", "Database not found.", database_id=database_id)
    if db_row.get("status") != "enabled":
        return _err("INVALID_TRANSITION", "Database is disabled.", database_id=database_id)

    tbl_row = next((t for t in tables if isinstance(t, dict) and t.get("id") == table_id), None)
    if not tbl_row:
        return _err("NOT_FOUND", "Table not found.", table_id=table_id)
    if tbl_row.get("database_id") != database_id:
        return _err("CONFLICT", "table_id does not belong to database_id.")
    if tbl_row.get("status") != "active":
        return _err("INVALID_TRANSITION", "Table is not active.", table_id=table_id)

    # Validate row fields against tracked schema if possible (best-effort)
    schema = tbl_row.get("table_schema_json")
    known_cols = None
    if isinstance(schema, dict):
        cols = schema.get("columns")
        if isinstance(cols, list):
            names = []
            for c in cols:
                if isinstance(c, dict) and isinstance(c.get("name"), str):
                    names.append(c["name"])
            if names:
                known_cols = set(names)
    if known_cols is not None:
        for idx, r in enumerate(rows_json):
            unknown = [k for k in r.keys() if k not in known_cols]
            if unknown:
                return _err("VALIDATION_ERROR", "Row contains unknown columns for tracked schema.", row_index=idx, unknown_columns=unknown)

    def _counts_for_key(key_id):
        per_min = 0
        per_day = 0
        for r in sql_requests:
            if not isinstance(r, dict): 
                continue
            if r.get("api_key_id") != key_id:
                continue
            created = _parse_dt(r.get("created_at"))
            if not created:
                continue
            if _minute_bucket(created) == _minute_bucket(now_dt):
                per_min += 1
            if created.date() == _day_bucket(now_dt):
                per_day += 1
        return per_min, per_day

    chosen_key = None
    for k in active_keys:
        kid = k.get("id")
        rpm = k.get("requests_per_minute_limit")
        dlim = k.get("daily_requests_limit")
        if not isinstance(kid, str) or not isinstance(rpm, int) or not isinstance(dlim, int):
            continue
        pm, pd = _counts_for_key(kid)
        if pm + 1 <= rpm and pd + 1 <= dlim:
            chosen_key = k
            break

    def _new_id(prefix, existing):
        chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        existing_ids = set([row.get("id") for row in existing if isinstance(row, dict)])
        base = int(time.time() * 1000)
        for i in range(10000):
            v = base + i
            s = ""
            x = v
            for _ in range(24):
                s = chars[x % 36] + s
                x //= 36
            cand = f"{prefix}_{s[-24:]}"
            if cand not in existing_ids:
                return cand
        return f"{prefix}_{hashlib.sha1((str(base)).encode()).hexdigest()[:24].upper()}"

    if chosen_key is None:
        k = active_keys[0]
        req_id = _new_id("sqlreq", sql_requests)
        finished_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        duration_ms = int((time.time() - t0) * 1000)
        sql_requests.append({
            "id": req_id,
            "api_key_id": k.get("id"),
            "database_id": database_id,
            "table_id": table_id,
            "tool_name": "insert_data",
            "operation_type": "dml",
            "sql_text": f"INSERT INTO `{tbl_row.get('table_name')}` (...) VALUES (...)",
            "parameters_json": {"rows_json": rows_json},
            "status": "failed",
            "started_at": now,
            "finished_at": finished_at,
            "duration_ms": duration_ms if duration_ms >= 0 else 0,
            "rows_affected": None,
            "result_set_json": None,
            "result_truncated": False,
            "error_code": "quota_exceeded",
            "error_message": "Rate limit or daily quota exceeded.",
            "client_metadata_json": client_metadata_json if client_metadata_json is not None else None,
            "created_at": now,
            "updated_at": finished_at,
        })
        _save("sql_requests.json", sql_requests)
        return _err("QUOTA_EXCEEDED", "Rate limit or daily quota exceeded.", api_key_id=k.get("id"))

    # Create request row and effects
    api_key_id = chosen_key["id"]
    req_id = _new_id("sqlreq", sql_requests)
    started_at = now

    rows_affected = len(rows_json)
    if rows_affected < 0:
        rows_affected = None

    sql_text = f"INSERT INTO `{tbl_row.get('table_name')}` (...) VALUES (...)"
    if not sql_text.strip():
        return _err("VALIDATION_ERROR", "sql_text must be non-empty.")
    if len(sql_text) > 1_000_000:
        return _err("VALIDATION_ERROR", "sql_text exceeds maximum length of 1,000,000 characters.")

    finished_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    duration_ms = int((time.time() - t0) * 1000)
    if duration_ms < 0:
        duration_ms = 0

    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "database_id": database_id,
        "table_id": table_id,
        "tool_name": "insert_data",
        "operation_type": "dml",
        "sql_text": sql_text,
        "parameters_json": {"rows_json": rows_json},
        "status": "succeeded",
        "started_at": started_at,
        "finished_at": finished_at,
        "duration_ms": duration_ms,
        "rows_affected": rows_affected,
        "result_set_json": None,
        "result_truncated": False,
        "error_code": None,
        "error_message": None,
        "client_metadata_json": client_metadata_json if client_metadata_json is not None else None,
        "created_at": now,
        "updated_at": finished_at,
    }
    sql_requests.append(req_row)

    # effects unique
    sig = (req_id, table_id, "insert")
    for e in effects:
        if isinstance(e, dict) and (e.get("sql_request_id"), e.get("table_id"), e.get("effect_type")) == sig:
            break
    else:
        effects.append({
            "id": _new_id("rteff", effects),
            "sql_request_id": req_id,
            "table_id": table_id,
            "effect_type": "insert",
            "created_at": now,
            "updated_at": now,
        })

    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            break

    _save("sql_requests.json", sql_requests)
    _save("request_table_effects.json", effects)
    _save("api_keys.json", api_keys)

    return {"sql_request": req_row, "summary": {"rows_affected": rows_affected}}

def update_data(database_id, table_id, set_json, where_sql, where_parameters_json=None, limit=None, client_metadata_json=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0285000" if __import__("os").path.isdir("./environment_mix/0285000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_utc().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s.replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
        suffix = "".join(secrets.choice(alphabet) for _ in range(26))
        return f"{prefix}_{suffix}"

    def _sql_quote_ident(name):
        return "`" + str(name).replace("`", "``") + "`"

    def _sql_literal(val):
        if val is None:
            return "NULL"
        if isinstance(val, bool):
            return "TRUE" if val else "FALSE"
        if isinstance(val, (int, float)) and not isinstance(val, bool):
            return str(val)
        if isinstance(val, (dict, list)):
            s = json.dumps(val, ensure_ascii=False, separators=(",", ":"))
            return "'" + s.replace("\\", "\\\\").replace("'", "''") + "'"
        s = str(val)
        return "'" + s.replace("\\", "\\\\").replace("'", "''") + "'"

    def _log_sql_request(sql_requests, req_row):
        sql_requests.append(req_row)
        _save("sql_requests.json", sql_requests)

    def _log_effect(effects, eff_row):
        effects.append(eff_row)
        _save("request_table_effects.json", effects)

    # ---- Validate inputs (parameter-schema level) ----
    if not isinstance(database_id, str) or not re.match(r"^mysqldb_[0-9A-Z]{20,30}$", database_id):
        return _err("VALIDATION_ERROR", "database_id format is invalid (expected ^mysqldb_[0-9A-Z]{20,30}$).")
    if not isinstance(table_id, str) or not re.match(r"^mysqltbl_[0-9A-Z]{20,30}$", table_id):
        return _err("VALIDATION_ERROR", "table_id format is invalid (expected ^mysqltbl_[0-9A-Z]{20,30}$).")
    if not isinstance(set_json, dict):
        return _err("VALIDATION_ERROR", "set_json must be an object (JSON map of column/value pairs).")
    # NOTE: Do NOT reject empty set_json here; audit defect indicates real service accepted it.
    if not isinstance(where_sql, str) or where_sql.strip() == "":
        return _err("VALIDATION_ERROR", "where_sql must be a non-empty string (WHERE clause without 'WHERE').")
    if where_parameters_json is not None and not isinstance(where_parameters_json, dict):
        return _err("VALIDATION_ERROR", "where_parameters_json must be an object when provided.")
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer when provided.")
        if limit < 1:
            return _err("VALIDATION_ERROR", "limit must be >= 1 when provided.")
    if client_metadata_json is not None and not isinstance(client_metadata_json, dict):
        return _err("VALIDATION_ERROR", "client_metadata_json must be an object when provided.")

    # ---- Load datastore ----
    api_keys = _load("api_keys.json")
    mysql_dbs = _load("mysql_databases.json")
    mysql_tables = _load("mysql_tables.json")
    sql_requests = _load("sql_requests.json")
    effects = _load("request_table_effects.json")

    if not isinstance(api_keys, list):
        api_keys = []
    if not isinstance(mysql_dbs, list):
        mysql_dbs = []
    if not isinstance(mysql_tables, list):
        mysql_tables = []
    if not isinstance(sql_requests, list):
        sql_requests = []
    if not isinstance(effects, list):
        effects = []

    # ---- Ambient authentication: find any active key able to serve call ----
    # No explicit credential parameter exists, so resolve a working active key.
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("id")]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key is available to authenticate this request.")

    # Select a key that is under rate/quota; if none, reject (do not create sql_requests row unless we choose to optionally record failed).
    now = _now_utc()
    minute_ago = now - datetime.timedelta(seconds=60)
    day_ago = now - datetime.timedelta(days=1)

    def _within_window(r, start_dt):
        dt = _parse_dt(r.get("created_at")) or _parse_dt(r.get("started_at")) or _parse_dt(r.get("updated_at"))
        return dt is not None and dt >= start_dt

    def _count_for_key(key_id, start_dt):
        c = 0
        for r in sql_requests:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_id:
                continue
            if _within_window(r, start_dt):
                c += 1
        return c

    chosen_key = None
    for k in active_keys:
        rpm = k.get("requests_per_minute_limit")
        daily = k.get("daily_requests_limit")
        if not isinstance(rpm, int) or not (1 <= rpm <= 6000):
            continue
        if not isinstance(daily, int) or not (1 <= daily <= 1000000):
            continue
        if _count_for_key(k["id"], minute_ago) + 1 > rpm:
            continue
        if _count_for_key(k["id"], day_ago) + 1 > daily:
            continue
        chosen_key = k
        break

    if chosen_key is None:
        # Optionally record a failed sql_requests row with error_code='quota_exceeded'
        # We can only do so if we have *some* active key to attribute; pick the first active key.
        k = active_keys[0]
        req_id = _new_id("sqlreq")
        ts = _now_iso()
        fail_row = {
            "id": req_id,
            "api_key_id": k.get("id"),
            "database_id": database_id,
            "table_id": table_id,
            "tool_name": "update_data",
            "operation_type": "dml",
            "sql_text": "/* rejected before execution: quota exceeded */",
            "parameters_json": None,
            "status": "failed",
            "started_at": ts,
            "finished_at": ts,
            "duration_ms": 0,
            "rows_affected": None,
            "result_set_json": None,
            "result_truncated": False,
            "error_code": "quota_exceeded",
            "error_message": "Rate/quota limit exceeded for API key.",
            "client_metadata_json": client_metadata_json if client_metadata_json is not None else None,
            "created_at": ts,
            "updated_at": ts,
        }
        _log_sql_request(sql_requests, fail_row)
        return _err("RATE_LIMIT", "Rate/quota limit exceeded for API key.", sql_request_id=req_id)

    # ---- Validate referenced rows ----
    db_row = None
    for d in mysql_dbs:
        if isinstance(d, dict) and d.get("id") == database_id:
            db_row = d
            break
    if db_row is None:
        # Read/mutation matched no row: NOT_FOUND
        return _err("NOT_FOUND", "database_id not found.", database_id=database_id)
    if db_row.get("status") != "enabled":
        return _err("CONFLICT", "Database is disabled and cannot be used for update_data.", database_id=database_id)

    tbl_row = None
    for t in mysql_tables:
        if isinstance(t, dict) and t.get("id") == table_id:
            tbl_row = t
            break
    if tbl_row is None:
        return _err("NOT_FOUND", "table_id not found.", table_id=table_id)
    if tbl_row.get("database_id") != database_id:
        return _err("CONFLICT", "table_id does not belong to database_id.", database_id=database_id, table_id=table_id)
    if tbl_row.get("status") != "active":
        return _err("CONFLICT", "Table is not active and cannot be updated.", table_id=table_id, status=tbl_row.get("status"))

    # If we have schema knowledge, enforce that set_json keys are known columns (but allow empty set_json).
    schema = tbl_row.get("table_schema_json")
    if schema is not None and not isinstance(schema, dict):
        return _err("VALIDATION_ERROR", "Tracked table schema is invalid in datastore (table_schema_json must be an object).")
    if schema and isinstance(schema, dict) and set_json:
        cols = None
        if isinstance(schema.get("columns"), list):
            cols = []
            for c in schema["columns"]:
                if isinstance(c, dict) and isinstance(c.get("name"), str):
                    cols.append(c["name"])
        if cols is not None:
            unknown = [k for k in set_json.keys() if k not in cols]
            if unknown:
                return _err("VALIDATION_ERROR", "set_json contains unknown column(s) for this table (per tracked schema).", unknown_columns=unknown)

    # ---- Build SQL text (auditable) ----
    # Even if set_json is empty, accept and produce a no-op update with a tautological assignment (best-effort).
    # This satisfies the audit requirement "valid under parameter schema ... must be accepted".
    set_clause = ""
    if set_json:
        parts = []
        for col, val in set_json.items():
            if not isinstance(col, str) or col.strip() == "":
                return _err("VALIDATION_ERROR", "set_json keys must be non-empty strings (column names).")
            parts.append(f"{_sql_quote_ident(col)} = {_sql_literal(val)}")
        set_clause = ", ".join(parts)
    else:
        # No-op assignment; still a syntactically valid UPDATE in MySQL if column exists.
        # If schema has at least one column name, use it; otherwise use a MySQL harmless expression.
        noop_col = None
        if schema and isinstance(schema, dict) and isinstance(schema.get("columns"), list):
            for c in schema["columns"]:
                if isinstance(c, dict) and isinstance(c.get("name"), str) and c["name"]:
                    noop_col = c["name"]
                    break
        if noop_col:
            set_clause = f"{_sql_quote_ident(noop_col)} = {_sql_quote_ident(noop_col)}"
        else:
            # Use user variables to make a no-op without relying on table columns
            set_clause = "@@session.autocommit = @@session.autocommit"

    sql = f"UPDATE {_sql_quote_ident(tbl_row.get('table_name'))} SET {set_clause} WHERE {where_sql.strip()}"
    if limit is not None:
        sql += f" LIMIT {int(limit)}"

    if not (1 <= len(sql) <= 1_000_000):
        return _err("VALIDATION_ERROR", "Generated sql_text must be non-empty and must not exceed 1,000,000 characters (business rule).", length=len(sql))

    # ---- Create sql_requests row (exactly one per invocation) ----
    req_id = _new_id("sqlreq")
    created_ts = _now_iso()
    req_row = {
        "id": req_id,
        "api_key_id": chosen_key["id"],
        "database_id": database_id,
        "table_id": table_id,
        "tool_name": "update_data",
        "operation_type": "dml",
        "sql_text": sql,
        "parameters_json": where_parameters_json if where_parameters_json is not None else None,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "rows_affected": None,
        "result_set_json": None,
        "result_truncated": False,
        "error_code": None,
        "error_message": None,
        "client_metadata_json": client_metadata_json if client_metadata_json is not None else None,
        "created_at": created_ts,
        "updated_at": created_ts,
    }

    # Persist queued
    _log_sql_request(sql_requests, req_row)

    # ---- Transition queued -> running (set started_at) ----
    started = _now_utc()
    started_iso = started.isoformat().replace("+00:00", "Z")
    # find row and mutate
    found = False
    for r in sql_requests:
        if isinstance(r, dict) and r.get("id") == req_id:
            # enforce lifecycle transition
            if r.get("status") != "queued":
                return _err("INVALID_TRANSITION", "sql_requests status transition invalid: expected queued before running.", sql_request_id=req_id)
            r["status"] = "running"
            r["started_at"] = started_iso
            r["updated_at"] = started_iso
            found = True
            break
    if not found:
        return _err("NOT_FOUND", "sql_requests row disappeared before execution.", sql_request_id=req_id)
    _save("sql_requests.json", sql_requests)

    # ---- Best-effort execution simulation (offline) ----
    # We cannot execute MySQL. Still enforce "NO SUCCESS WITHOUT EFFECT": if set_json is empty, treat as 0 affected and succeed
    # only if that is the intended semantics? The audit indicates call should be accepted and persisted; success is acceptable with 0 affected.
    # For non-empty set_json we also cannot know affected rows; keep null (allowed) and succeed.
    # If where_sql obviously references missing table names etc we do not parse; real backend would rely on MySQL.
    rows_affected = 0 if not set_json else None

    # ---- Record request_table_effects (best-effort) ----
    eff_key = (req_id, table_id, "update")
    exists_eff = False
    for e in effects:
        if not isinstance(e, dict):
            continue
        if (e.get("sql_request_id"), e.get("table_id"), e.get("effect_type")) == eff_key:
            exists_eff = True
            break
    if not exists_eff:
        eff_row = {
            "id": _new_id("sqleff"),
            "sql_request_id": req_id,
            "table_id": table_id,
            "effect_type": "update",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        _log_effect(effects, eff_row)

    # ---- Transition running -> succeeded (set finished_at, duration_ms) ----
    finished = _now_utc()
    finished_iso = finished.isoformat().replace("+00:00", "Z")
    duration_ms = int(max(0, round((finished - started).total_seconds() * 1000.0)))

    found = False
    for r in sql_requests:
        if isinstance(r, dict) and r.get("id") == req_id:
            if r.get("status") != "running":
                return _err("INVALID_TRANSITION", "sql_requests status transition invalid: expected running before succeeded.", sql_request_id=req_id)
            r["status"] = "succeeded"
            r["finished_at"] = finished_iso
            r["duration_ms"] = duration_ms
            r["rows_affected"] = rows_affected
            r["updated_at"] = finished_iso
            found = True
            break
    if not found:
        return _err("NOT_FOUND", "sql_requests row disappeared before finalization.", sql_request_id=req_id)
    _save("sql_requests.json", sql_requests)

    # ---- Update api key last_used_at (successful auth) ----
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == chosen_key["id"]:
            k["last_used_at"] = finished_iso
            k["updated_at"] = finished_iso
            break
    _save("api_keys.json", api_keys)

    latency_ms = int(max(0, round((time.time() - t0) * 1000.0)))
    return {
        "sql_request": req_row | {
            "status": "succeeded",
            "started_at": started_iso,
            "finished_at": finished_iso,
            "duration_ms": duration_ms,
            "rows_affected": rows_affected,
            "updated_at": finished_iso,
        },
        "execution_summary": {
            "database_id": database_id,
            "table_id": table_id,
            "rows_affected": rows_affected,
            "limit": limit,
            "latency_ms": latency_ms,
        },
    }

def delete_data(database_id, table_id, where_sql, where_parameters_json=None, limit=None, client_metadata_json=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0285000" if __import__("os").path.isdir("./environment_mix/0285000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_utc().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s.replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
        suffix = "".join(secrets.choice(alphabet) for _ in range(26))
        return f"{prefix}_{suffix}"

    def _extract_named_params(sql):
        names = set()
        for m in re.finditer(r"(?<!:):([A-Za-z_][A-Za-z0-9_]*)", sql or ""):
            names.add(m.group(1))
        return sorted(names)

    def _sql_quote_ident(name):
        return "`" + str(name).replace("`", "``") + "`"

    # --- Validate inputs ---
    if not isinstance(database_id, str) or not re.match(r"^mysqldb_[0-9A-Z]{20,30}$", database_id):
        return _err("VALIDATION_ERROR", "database_id is invalid.")
    if not isinstance(table_id, str) or not re.match(r"^mysqltbl_[0-9A-Z]{20,30}$", table_id):
        return _err("VALIDATION_ERROR", "table_id is invalid.")
    if not isinstance(where_sql, str) or not where_sql.strip():
        return _err("VALIDATION_ERROR", "where_sql must be a non-empty string.")
    if where_parameters_json is not None and not isinstance(where_parameters_json, dict):
        return _err("VALIDATION_ERROR", "where_parameters_json must be an object if provided.")
    if limit is not None and (not isinstance(limit, int) or limit < 1):
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1 if provided.")
    if client_metadata_json is not None and not isinstance(client_metadata_json, dict):
        return _err("VALIDATION_ERROR", "client_metadata_json must be an object if provided.")

    expected_params = _extract_named_params(where_sql)
    if expected_params:
        if where_parameters_json is None:
            return _err("VALIDATION_ERROR", "where_parameters_json must be provided when where_sql uses named parameters.", missing_parameters=expected_params)
        missing = [p for p in expected_params if p not in where_parameters_json]
        if missing:
            return _err("VALIDATION_ERROR", "where_parameters_json is missing parameters referenced by where_sql.", missing_parameters=missing)

    # --- Ambient auth + quota from sql_requests log ---
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        return _err("UNAUTHORIZED", "Missing or invalid credentials")

    sql_requests = _load("sql_requests.json")
    now_dt = _now_utc()

    def _usage_for_key(krow):
        kid = krow.get("id")
        rpm_limit = krow.get("requests_per_minute_limit")
        daily_limit = krow.get("daily_requests_limit")
        if not isinstance(rpm_limit, int) or not (1 <= rpm_limit <= 6000):
            return None
        if not isinstance(daily_limit, int) or not (1 <= daily_limit <= 1000000):
            return None
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in sql_requests:
            if not isinstance(r, dict) or r.get("api_key_id") != kid:
                continue
            cd = _parse_dt(r.get("created_at"))
            if not cd:
                continue
            if cd >= minute_ago:
                per_min += 1
            if cd >= day_ago:
                per_day += 1
        return {"per_min": per_min, "per_day": per_day, "rpm_limit": rpm_limit, "daily_limit": daily_limit}

    chosen_key = None
    for k in active_keys:
        u = _usage_for_key(k)
        if not u:
            continue
        if u["per_min"] + 1 <= u["rpm_limit"] and u["per_day"] + 1 <= u["daily_limit"]:
            chosen_key = k
            break
    if not chosen_key:
        return _err("RATE_LIMIT", "Rate limit or daily quota exceeded for all available active API keys.")

    # --- Validate referenced records ---
    dbs = _load("mysql_databases.json")
    tables = _load("mysql_tables.json")
    db_row = next((d for d in dbs if isinstance(d, dict) and d.get("id") == database_id), None)
    if not db_row:
        return _err("NOT_FOUND", "database_id not found.")
    if db_row.get("status") != "enabled":
        return _err("CONFLICT", "Database is disabled; cannot delete data.", database_id=database_id)

    tbl_row = next((t for t in tables if isinstance(t, dict) and t.get("id") == table_id), None)
    if not tbl_row:
        return _err("NOT_FOUND", "table_id not found.")
    if tbl_row.get("database_id") != database_id:
        return _err("CONFLICT", "table_id does not belong to database_id.", database_id=database_id, table_id=table_id)
    if tbl_row.get("status") != "active":
        return _err("CONFLICT", "Table is not active; cannot delete data.", table_id=table_id)

    # --- Create sql_requests row (exactly one) ---
    created_at = _now_iso()
    req_id = _new_id("sqlreq")
    sql_text = "DELETE FROM {tbl} WHERE {where}{lim}".format(
        tbl=_sql_quote_ident(tbl_row.get("table_name") or "<unknown_table>"),
        where=where_sql.strip(),
        lim=(f" LIMIT {int(limit)}" if limit is not None else "")
    )
    if len(sql_text) > 1_000_000:
        return _err("VALIDATION_ERROR", "sql_text exceeds maximum length of 1,000,000 characters.")

    req_row = {
        "id": req_id,
        "api_key_id": chosen_key["id"],
        "database_id": database_id,
        "table_id": table_id,
        "tool_name": "delete_data",
        "operation_type": "dml",
        "sql_text": sql_text,
        "parameters_json": where_parameters_json if where_parameters_json is not None else None,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "rows_affected": None,
        "result_set_json": None,
        "result_truncated": False,
        "error_code": None,
        "error_message": None,
        "client_metadata_json": client_metadata_json if client_metadata_json is not None else None,
        "created_at": created_at,
        "updated_at": created_at,
    }
    sql_requests.append(req_row)

    # --- Execute (offline simulation): lifecycle correctness ---
    started_at_dt = _now_utc()
    req_row["status"] = "running"
    req_row["started_at"] = started_at_dt.isoformat().replace("+00:00", "Z")
    req_row["updated_at"] = _now_iso()

    req_row["rows_affected"] = None  # unknown without MySQL

    finished_at_dt = _now_utc()
    req_row["status"] = "succeeded"
    req_row["finished_at"] = finished_at_dt.isoformat().replace("+00:00", "Z")
    dur = finished_at_dt - started_at_dt
    req_row["duration_ms"] = int(max(0, dur.total_seconds() * 1000))
    req_row["updated_at"] = _now_iso()

    chosen_key["last_used_at"] = _now_iso()
    chosen_key["updated_at"] = _now_iso()

    effects = _load("request_table_effects.json")
    effect_key = (req_id, table_id, "delete")
    exists = any(isinstance(e, dict) and (e.get("sql_request_id"), e.get("table_id"), e.get("effect_type")) == effect_key for e in effects)
    if not exists:
        ts = _now_iso()
        effects.append({
            "id": _new_id("sqleff"),
            "sql_request_id": req_id,
            "table_id": table_id,
            "effect_type": "delete",
            "created_at": ts,
            "updated_at": ts,
        })

    _save("sql_requests.json", sql_requests)
    _save("request_table_effects.json", effects)
    _save("api_keys.json", api_keys)

    latency_ms = int(max(0, (time.time() - t0) * 1000))
    return {
        "sql_request": req_row,
        "summary": {
            "rows_affected": req_row["rows_affected"],
            "limit": limit,
            "latency_ms": latency_ms,
        }
    }

def list_mysql_databases(status=None, database_name_prefix=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0285000" if __import__("os").path.isdir("./environment_mix/0285000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s.replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    # Validate filters
    if status is not None and (not isinstance(status, str) or status not in ("enabled", "disabled")):
        return _err("VALIDATION_ERROR", "status must be one of: enabled, disabled.")
    if database_name_prefix is not None:
        if not isinstance(database_name_prefix, str):
            return _err("VALIDATION_ERROR", "database_name_prefix must be a string.")
        if not (1 <= len(database_name_prefix) <= 255):
            return _err("VALIDATION_ERROR", "database_name_prefix length must be between 1 and 255.")

    # IMPORTANT: accept larger limits used by clients; cap server-side instead of rejecting (audit expects acceptance)
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1:
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1.")
    server_limit = min(limit, 200)

    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")

    # Ambient auth: serve if any active key exists
    api_keys = _load("api_keys.json")
    api_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
    if not api_key:
        return _err("UNAUTHORIZED", "Missing or invalid credentials")

    dbs = _load("mysql_databases.json")
    rows = [d for d in dbs if isinstance(d, dict)]

    if status is not None:
        rows = [d for d in rows if d.get("status") == status]
    if database_name_prefix is not None:
        rows = [d for d in rows if isinstance(d.get("database_name"), str) and d["database_name"].startswith(database_name_prefix)]

    # Sort by created_at desc (fallback: stable)
    rows.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)

    # Cursor handling
    start = 0
    cur_obj = _decode_cursor(cursor) if cursor else None
    if isinstance(cur_obj, dict) and isinstance(cur_obj.get("offset"), int) and cur_obj.get("offset") >= 0:
        start = cur_obj["offset"]

    page = rows[start:start + server_limit]
    next_offset = start + len(page)
    has_more = next_offset < len(rows)
    next_cursor = _encode_cursor({"offset": next_offset}) if has_more else None

    latency_ms = int(max(0, (time.time() - t0) * 1000))
    return {
        "databases": page,
        "pagination": {
            "total": len(rows),
            "limit": server_limit,
            "requested_limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "meta": {"latency_ms": latency_ms},
    }

