def list_mysql_tables(database_id, status=None, table_name_prefix=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0285000" if __import__("os").path.isdir("./environment_mix/0285000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if not isinstance(database_id, str) or not re.match(r"^mysqldb_[0-9A-Z]{20,30}$", database_id):
        return _err("VALIDATION_ERROR", "Invalid database_id format.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "dropped"):
            return _err("VALIDATION_ERROR", "Invalid status filter.")
    if table_name_prefix is not None:
        if not isinstance(table_name_prefix, str):
            return _err("VALIDATION_ERROR", "table_name_prefix must be a string.")
        if len(table_name_prefix) < 1 or len(table_name_prefix) > 255:
            return _err("VALIDATION_ERROR", "table_name_prefix length must be between 1 and 255.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
    if cursor is not None and (not isinstance(cursor, str) or not cursor):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")

    def _parse_iso(s):
        if not s:
            return None
        try:
            ss = s.replace("Z", "+00:00") if isinstance(s, str) else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _decode_cursor(cur):
        if cur is None:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    api_keys = _load("api_keys.json")
    dbs = _load("mysql_databases.json")
    tbls = _load("mysql_tables.json")

    # ambient auth
    active = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
    if not active:
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    db_row = next((d for d in dbs if isinstance(d, dict) and d.get("id") == database_id), None)
    if not db_row:
        return _err("NOT_FOUND", "Database not found.", database_id=database_id)

    rows = [t for t in tbls if isinstance(t, dict) and t.get("database_id") == database_id]
    if status is not None:
        rows = [t for t in rows if t.get("status") == status]
    if table_name_prefix is not None:
        rows = [t for t in rows if isinstance(t.get("table_name"), str) and t.get("table_name").startswith(table_name_prefix)]

    # order by created_at desc
    def _sort_key(t):
        dt = _parse_iso(t.get("created_at"))
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, t.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    start = 0
    if cursor is not None:
        c = _decode_cursor(cursor)
        if not isinstance(c, dict) or "created_at" not in c or "id" not in c:
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        c_dt = _parse_iso(c.get("created_at"))
        c_id = c.get("id")
        if c_dt is None or not isinstance(c_id, str):
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        for i, t in enumerate(rows):
            t_dt = _parse_iso(t.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            t_id = t.get("id") or ""
            if (t_dt, t_id) < (c_dt, c_id):
                start = i
                break
        else:
            start = len(rows)

    page = rows[start:start + limit]
    has_more = start + limit < len(rows)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor({"created_at": last.get("created_at"), "id": last.get("id")})

    latency_ms = int(max(0, (time.time() - t0) * 1000))
    return {
        "tables": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": latency_ms
        }
    }

def get_mysql_table(table_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0285000" if __import__("os").path.isdir("./environment_mix/0285000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s.replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    # Validate
    if not isinstance(table_id, str):
        return _err("VALIDATION_ERROR", "table_id must be a string")
    if not re.match(r"^mysqltbl_[0-9A-Z]{20,30}$", table_id):
        return _err("VALIDATION_ERROR", "table_id is invalid")

    # Ambient auth: any active api key
    api_keys = _load("api_keys.json")
    api_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
    if not api_key:
        return _err("UNAUTHORIZED", "Missing or invalid credentials")

    # Rate/quota best-effort: avoid naive/aware comparisons
    sql_requests = _load("sql_requests.json")
    now = datetime.datetime.now(datetime.timezone.utc)
    minute_ago = now - datetime.timedelta(seconds=60)
    day_ago = now - datetime.timedelta(days=1)

    def _created_dt(row):
        return _parse_dt(row.get("created_at")) if isinstance(row, dict) else None

    reqs_for_key = [r for r in sql_requests if isinstance(r, dict) and r.get("api_key_id") == api_key.get("id")]
    per_min = sum(1 for r in reqs_for_key if (cd := _created_dt(r)) and cd >= minute_ago)
    per_day = sum(1 for r in reqs_for_key if (cd := _created_dt(r)) and cd >= day_ago)

    rpm_limit = api_key.get("requests_per_minute_limit")
    daily_limit = api_key.get("daily_requests_limit")
    if isinstance(rpm_limit, int) and isinstance(daily_limit, int):
        if per_min + 1 > rpm_limit or per_day + 1 > daily_limit:
            return _err("RATE_LIMIT", "Rate limit or daily quota exceeded.")

    tables = _load("mysql_tables.json")
    row = next((t for t in tables if isinstance(t, dict) and t.get("id") == table_id), None)
    if not row:
        return _err("NOT_FOUND", "Table not found.")

    latency_ms = int(max(0, (time.time() - t0) * 1000))
    return {"table": row, "meta": {"latency_ms": latency_ms}}

def list_sql_requests(database_id=None, table_id=None, tool_name=None, operation_type=None, status=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

