        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s.replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    # Validate filters
    if database_id is not None and (not isinstance(database_id, str) or not re.match(r"^mysqldb_[0-9A-Z]{20,30}$", database_id)):
        return _err("VALIDATION_ERROR", "database_id is invalid")
    if table_id is not None and (not isinstance(table_id, str) or not re.match(r"^mysqltbl_[0-9A-Z]{20,30}$", table_id)):
        return _err("VALIDATION_ERROR", "table_id is invalid")
    if tool_name is not None and tool_name not in ["run_sql_query", "create_table", "insert_data", "update_data", "delete_data"]:
        return _err("VALIDATION_ERROR", "tool_name is invalid")
    # IMPORTANT: the store uses operation_type enum ["ddl","dml","read","admin"].
    # Accept client enum values and map them.
    op_map = {"query": "read", "ddl": "ddl", "insert": "dml", "update": "dml", "delete": "dml"}
    op_filter = None
    if operation_type is not None:
        if operation_type not in ["query", "ddl", "insert", "update", "delete"]:
            return _err("VALIDATION_ERROR", "operation_type is invalid")
        op_filter = op_map[operation_type]
    if status is not None and status not in ["queued", "running", "succeeded", "failed", "cancelled"]:
        return _err("VALIDATION_ERROR", "status is invalid")

    # Accept larger limits used by clients; cap to 200 rather than reject.
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1:
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
    server_limit = min(limit, 200)

    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")

    ca = _parse_dt(created_after) if created_after is not None else None
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be an RFC3339 date-time string.")
    cb = _parse_dt(created_before) if created_before is not None else None
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be an RFC3339 date-time string.")
    if ca and cb and cb < ca:
        return _err("VALIDATION_ERROR", "created_before must be greater than or equal to created_after.")

    # Ambient auth: any active key (list endpoint is per authenticated caller; with no explicit auth param we resolve any workable context)
    api_keys = _load("api_keys.json")
    api_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
    if not api_key:
        return _err("UNAUTHORIZED", "Missing or invalid credentials")

    reqs = _load("sql_requests.json")
    rows = [r for r in reqs if isinstance(r, dict)]

    # Filter by caller (best-effort: api_key_id must match the resolved key)
    kid = api_key.get("id")
    if isinstance(kid, str):
        rows = [r for r in rows if r.get("api_key_id") == kid]

    if database_id is not None:
        rows = [r for r in rows if r.get("database_id") == database_id]
    if table_id is not None:
        rows = [r for r in rows if r.get("table_id") == table_id]
    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if op_filter is not None:
        rows = [r for r in rows if r.get("operation_type") == op_filter]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if ca is not None:
        rows = [r for r in rows if (dt := _parse_dt(r.get("created_at"))) and dt >= ca]
    if cb is not None:
        rows = [r for r in rows if (dt := _parse_dt(r.get("created_at"))) and dt < cb]

    # Sort created_at desc
    rows.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)

    # Pagination by offset cursor
    start = 0
    cur_obj = _decode_cursor(cursor) if cursor else None
    if isinstance(cur_obj, dict) and isinstance(cur_obj.get("offset"), int) and cur_obj.get("offset") >= 0:
        start = cur_obj["offset"]

    page = rows[start:start + server_limit]
    next_offset = start + len(page)
    has_more = next_offset < len(rows)
    next_cursor = _encode_cursor({"offset": next_offset}) if has_more else None

    latency_ms = int(max(0, (time.time() - t0) * 1000))
    return {
        "sql_requests": page,
        "pagination": {
            "total": len(rows),
            "limit": server_limit,
            "requested_limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "meta": {"latency_ms": latency_ms},
    }

def get_whoami(include_usage=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0285000" if __import__("os").path.isdir("./environment_mix/0285000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s.replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    if include_usage is None:
        include_usage = False
    if not isinstance(include_usage, bool):
        return _err("VALIDATION_ERROR", "include_usage must be a boolean")

    # Ambient auth: choose any active key (do not require uniqueness)
    api_keys = _load("api_keys.json")
    api_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
    if not api_key:
        return _err("UNAUTHORIZED", "Missing or invalid credentials")

    resp = {
        "api_key": {
            "id": api_key.get("id"),
            "name": api_key.get("name"),
            "status": api_key.get("status"),
            "key_prefix": api_key.get("key_prefix"),
            "created_at": api_key.get("created_at"),
            "updated_at": api_key.get("updated_at"),
            "last_used_at": api_key.get("last_used_at"),
            "requests_per_minute_limit": api_key.get("requests_per_minute_limit"),
            "daily_requests_limit": api_key.get("daily_requests_limit"),
            "scopes": ["mysql:read", "mysql:write", "audit:read"],
        }
    }

    if include_usage:
        sql_requests = _load("sql_requests.json")
        now = _now_utc()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)
        kid = api_key.get("id")
        reqs_for_key = [r for r in sql_requests if isinstance(r, dict) and r.get("api_key_id") == kid]
        per_min = sum(1 for r in reqs_for_key if (cd := _parse_dt(r.get("created_at"))) and cd >= minute_ago)
        per_day = sum(1 for r in reqs_for_key if (cd := _parse_dt(r.get("created_at"))) and cd >= day_ago)
        resp["usage"] = {
            "requests_last_minute": per_min,
            "requests_last_24h": per_day,
            "minute_window_started_at": minute_ago.isoformat().replace("+00:00", "Z"),
            "day_window_started_at": day_ago.isoformat().replace("+00:00", "Z"),
        }

    latency_ms = int(max(0, (time.time() - t0) * 1000))
    resp["meta"] = {"latency_ms": latency_ms}
    return resp
